        id: 'revision.children-parents',
        kind: 'conflicts',
        origin: 'git',
        source: 'Git 2.55.0 revision.c:handle_revision_opt/setup_revisions',
        reason: 'Children output conflicts with explicit or implicit parent rewriting.',
        when: {
          key: 'children',
          test: 'active',
        },
        others: [
          {
            key: 'rewrite-parents',
            test: 'active',
          },
          {
            key: 'graph',
            test: 'active',
          },
        ],
